-- GENERATED by `wfj generate` from data/gossip/gossip-c8.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["c80945da3b27d4ce"] = { "Non ho mai visto un {name} così grosso... e viene dritto verso di noi!", "." },
  ["c812ed45a868b3d2"] = { "Togliti il travestimento, se non vuoi sentire il morso della mia lama quando la furia avrà preso il controllo.", "." },
  ["c8190c8f52da4b66"] = { "Salute, {class}. Hai un'aria familiare... ci siamo già visti?\n\nBe', se ci siamo già visti, allora... di sicuro ti è stato dato un codice segreto. Dimmi il tuo codice e ti darò un regalo!", "." },
  ["c81e765f6b63a379"] = { "Se cerchi una banca, il tuo viaggio ti porta nel cuore di Darnassus. Lì troverai un posto dove custodire i tuoi tesori.", "." },
  ["c824892fa09c0607"] = { "Eccoli! Difendetevi!", "." },
  ["c82650503c79b173"] = { "Devi salvarci!", "." },
  ["c8341f87bd1a7647"] = { "Chi osa evocare il potere del vuoto?", "." },
  ["c83421eee372e977"] = { "Ho proprio l'incantesimo giusto per aprire questa porta. Peccato che le porte delle celle non fossero chiuse in modo così approssimativo.", "." },
  ["c838607d71a1ad57"] = { "Non posso più nemmeno visitare in pace la tomba di mio padre.", "." },
  ["c83b07516f3d8c25"] = { "<Sveglia Tarsis.>", "." },
  ["c840dda31e78cf1c"] = { "Che la Luce sia con te, signore.", "." },
  ["c844f02cebc00d2c"] = { "Questo è leggermente meglio dell'ultimo. Tuttavia, soffre ancora della stessa fragile struttura ossea degli altri. Quando ne evochi uno così, sei sulla strada giusta.", "." },
  ["c84a62dcd44ac730"] = { "Serviamo Thrall con grande orgoglio. Andremo lontano quanto serve per sconfiggere il nemico.", "." },
  ["c854482cd468b490"] = { "Almeno ci guadagneremo la morte!", "." },
  ["c8611eaec34d2c5e"] = { "Hai fatto bene, {name}. Ora ti insegnerò l'incantesimo per evocare l'ombra del Vuoto.\n\nIl potere che ha scatenato contro di te ora è tuo da comandare. Usalo con saggezza.", "." },
  ["c8620fb75095e29b"] = { "Guarda, là! Vicino all'⟦Hive'Regal=Alveare Regal⟧! Quello è... un verme delle sabbie?!", "." },
  ["c86a58cf5369c5c6"] = { "Se vuoi diventare <mio/mia> <allievo/allieva>, dovrai portare a termine un incarico per me. Dimostra di valere qualcosa, e potrei persino pensare di ricompensarti.", "." },
  ["c872702994b68e0f"] = { "La morte è solo una porta verso la rinascita. La covata risorgerà.", "." },
  ["c8789fa5dd22ee95"] = { "Il ⟦The Loch=Loch⟧ ora appartiene alla tribù Scheggiadura, {name}! E ora muori!", "." },
  ["c881268f27bbbb53"] = { "L'anziano Bladeswift percorre i sentieri di Darnassus, in cima a Teldrassil.", "." },
  ["c88a105703ba58eb"] = { "Da quando le ombre si sono prese ⟦Duskwood=Boscovespro⟧ non riesco più a dormire. Non chiudo occhio per i suoni spettrali delle urla portate dalla brezza. Sembrano quasi agnelli che urlano, e non smettono mai.", "." },
  ["c88cb9de5b8920e9"] = { "Anche se questa terra la chiamiamo ⟦Barrens=Savane⟧, per chi sa dove guardare brulica di vita.", "." },
  ["c88f037a2279fd53"] = { "Mmh, una mano lava l'altra. Se fai quello che ti chiedo, e lo fai bene, forse potremo parlare del tuo addestramento.", "." },
  ["c8935b76a6f5f814"] = { "Mentre Greta concentra le sue energie sulla riconquista di Jaedenar e su coloro che ritiene i principali responsabili della corruzione qui nel ⟦Felwood=Vilbosco⟧, io passo il mio tempo a studiare gli effetti che la corruzione ha avuto sulla terra.\n\nIn che modo ha colpito le creature di queste terre? Cosa bisogna fare per porre fine al loro dolore?\n\nPurtroppo la corruzione è così profonda che troppo spesso la risposta è il sonno eterno.", "." },
  ["c8a98ead1b48c396"] = { "Salute. Sono qui per addestrare ogni {class}, e tu sei <un/una> {class}.", "." },
  ["c8aba30bb2f6b9e3"] = { "Grazie, {name}. E buona fortuna.", "." },
  ["c8b4171e85086a60"] = { "Anche se me ne vado in pace, avete tutti la mia eterna gratitudine. Grazie per avermi tolto la maledizione della mia follia e della mia avidità.", "." },
  ["c8b6f4d3d59c6462"] = { "La tua comprensione del cuoio è più profonda della mia. Forse dovresti far visita al tauren Krulmoo Fullmoon a Camp Taurajo, nelle ⟦Barrens=Savane⟧. Ha molte conoscenze da offrire a chi ha il tuo talento.", "." },
  ["c8bcac74562e8dda"] = { "I ⟦Razorfen Downs=Sotterranei di Lamaspina⟧ si trovano all'estremità meridionale delle ⟦Barrens=Savane⟧, sul lato est della strada.", "." },
  ["c8c52ccf44aecb19"] = { "Va' a cercare Zando'zan nel Cleft of Shadow. Ci sono un paio di tunnel che scendono in quella caverna, uno appena a sud della Valle della Saggezza e l'altro in The Drag.", "." },
  ["c8c81d7696f41231"] = { "La mia qualifica è Specialista in Gestione dei Rifiuti.", "." },
  ["c8d45aa942a7e230"] = { "Sono qui! Il tuo dominio su questa terra è finito!", "." },
  ["c8db931454e35501"] = { "Padre Cobb è quello con cui devi parlare. Lo trovi sotto l'⟦Spirit Rise=Altura degli Spiriti⟧, nella grotta delle Pozze delle Visioni.", "." },
  ["c8de062c58b11b9c"] = { "Avvicinati, giovane. Ai miei tempi sentivo il fremito del cuore di una preda che batteva, ma ora devi alzare la voce se vuoi che le tue parole siano ascoltate.", "." },
  ["c8f47f457aa6eb58"] = { "Venite, venite tutti! Benvenuti alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Non siate timidi. Avvicinatevi a Lhara e compratevi un manufatto esotico da terre lontane. Se siete tra i pochi fortunati che hanno trovato delle Carte di Lunacupa, scambiate due parole con il professor Paleo. Fame? Sete? Siete fortunati! Qui ci sono rinfreschi da Sylannia e Stamp. Vi consiglio la ⟦Darkmoon Special Reserve=Riserva Speciale di Lunacupa⟧ per mandar giù un po' di ⟦Red Hot Wings=Alette Piccanti⟧. E se è il futuro che cercate, correte, non camminate, a parlare con Sayge.", "." },
  ["c8fc9407be25d4d8"] = { "Sergente Hartman! Devo comprare un altro Purificatore per Bombe Puzzolenti!", "." },
  ["c8fd282844930669"] = { "Cerca Yelmak's Alchemy and Potions. La trovi in mezzo a The Drag, a ovest del grande albero.", "." },
})
